pe": "string"}, "NarrativeBlock": {"additionalProperties": false, "description": "Human-readable synthesis linked to the atomic claims it summarizes.", "properties": {"claim_ids": {"items": {"type": "string"}, "title": "Claim Ids", "type": "array"}, "text": {"minLength": 1, "title": "Text", "type": "string"}}, "required": ["text"], "title": "NarrativeBlock", "type": "object"}, "Provenance": {"enum": ["primary", "secondary", "user-provided", "inference", "analyst-judgment"], "title": "Provenance", "type": "string"}, "WatchIndicator": {"additionalProperties": false, "properties": {"basis_claim_ids": {"items": {"type": "string"}, "title": "Basis Claim Ids", "type": "array"}, "indicator": {"minLength": 1, "title": "Indicator", "type": "string"}, "indicator_id": {"pattern": "^[A-Za-z][A-Za-z0-9._-]{0,63}$", "title": "Indicator Id", "type": "string"}, "posture_change": {"minLength": 1, "title": "Posture Change", "type": "string"}, "trigger": {"minLength": 1, "title": "Trigger", "type": "string"}}, "required": ["indicator_id", "indicator", "trigger", "posture_change"], "title": "WatchIndicator", "type": "object"}}, "additionalProperties": false, "properties": {"artifact_id": {"pattern": "^[A-Za-z][A-Za-z0-9._-]{0,127}$", "title": "Artifact Id", "type": "string"}, "audience": {"minLength": 1, "title": "Audience", "type": "string"}, "bottom_line": {"$ref": "#/$defs/NarrativeBlock"}, "change_conditions": {"items": {"type": "string"}, "title": "Change Conditions", "type": "array"}, "claims": {"items": {"$ref": "#/$defs/MemoClaim"}, "title": "Claims", "type": "array"}, "confidence": {"$ref": "#/$defs/Confidence"}, "decision": {"minLength": 1, "title": "Decision", "type": "string"}, "evidence_mode": {"$ref": "#/$defs/EvidenceMode"}, "indicators": {"items": {"$ref": "#/$defs/WatchIndicator"}, "title": "Indicators", "type": "array"}, "key_unknowns": {"items": {"type": "string"}, "title": "Key Unknowns", "type": "array"}, "limitations": {"items": {"type": "string"}, "title": "Limitations", "type": "array"}, "mode": {"$ref": "#/$defs/MemoMode"}, "options": {"items": {"$ref": "#/$defs/DecisionOption"}, "title": "Options", "type": "array"}, "question": {"minLength": 1, "title": "Question", "type": "string"}, "schema_version": {"const": "gtta.memo@1.0", "title": "Schema Version", "type": "string"}, "sections": {"additionalProperties": {"$ref": "#/$defs/NarrativeBlock"}, "title": "Sections", "type": "object"}, "time_horizon": {"minLength": 1, "title": "Time Horizon", "type": "string"}, "title": {"minLength": 1, "title": "Title", "type": "string"}}, "required": ["schema_version", "artifact_id", "title", "question", "decision", "audience", "time_horizon", "mode", "evidence_mode", "bottom_line", "confidence"], "title": "MemoArtifact", "type": "object"}
